		const aScore = a.evaluatedEntries >= 10 ? a.simulatedRoiPct + a.currentSignal.score : a.currentSignal.score;
		return (b.evaluatedEntries >= 10 ? b.simulatedRoiPct + b.currentSignal.score : b.currentSignal.score) - aScore;
